import kiln


def first_item(shelf):
    """Return the item in the first slot of `shelf`.

    The first slot is slot index 0. If the shelf has no slots (size == 0),
    return None.
    """
    if getattr(shelf, "size", 0) == 0:
        return None
    return shelf.get(0)

def first_item(shelf):
    """Return the item in the first slot (slot 1) of the given shelf."""
    return shelf.get(1)

import kiln


def combine(a, b) -> list:
    """Combine two lists of (key, qty) records.

    Sums quantities for duplicate keys and returns a list sorted by key.
    """
    # Use direct aggregation as requested.
    totals = {}

    if a:
        for key, qty in a:
            totals[key] = totals.get(key, 0) + qty

    if b:
        for key, qty in b:
            totals[key] = totals.get(key, 0) + qty

    return sorted(totals.items(), key=lambda kv: kv[0])

