def on_hand(inv: Any, code: str) -> int:
    """Return units of product `code` currently on hand in `inv`."""
    normalized = kiln.sku(code)
    return inv.count(normalized)


if __name__ == "__main__":
    # Lightweight consistency check: verify normalization + count lookup.
    # Use the real kiln.Inventory if available; otherwise fall back to a small fake.
    try:
        inv = kiln.Inventory()
    except Exception:
        class _FakeInv:
            def __init__(self):
                self._d = {}

            def add(self, code: str, qty: int) -> None:
                self._d[kiln.sku(code)] = self._d.get(kiln.sku(code), 0) + qty

