def month_revenue_dollars(ledger, year, month) -> float:
    """Return the total dollars of ledger 'sales' entries for a given year/month."""
    from datetime import date, timedelta

    # Basic coercion/validation
    year = int(year)
    month = int(month)
    if not 1 <= month <= 12:
        raise ValueError("month must be in 1..12")

    first_day = date(year, month, 1)
    # Inclusive end-of-month
    if month < 12:
        last_day = date(year, month + 1, 1) - timedelta(days=1)
    else:
        last_day = date(year + 1, 1, 1) - timedelta(days=1)

    total = 0
    for d, account, amount in ledger.entries():
        if first_day <= d <= last_day and account == "sales":
            total += amount

    return float(total)

"""Utility to check activity in a kiln Ledger.

Only provides :func:`has_activity`.
"""

from __future__ import annotations

import datetime
from typing import Any, Protocol


class _LedgerLike(Protocol):
    def entries(self) -> list[tuple[datetime.date, Any, int]]:
        """Return ledger entries as (date, account, amount)."""


def has_activity(ledger: _LedgerLike, day: datetime.date) -> bool:
    """Return True iff *ledger* contains at least one entry dated exactly *day*."""

    for entry in ledger.entries():
        # entry is documented as (date, account, amount)
        if entry[0] == day:
            return True
    return False

import kiln


def receive(inv, shipment) -> int:
    canonical_codes = set()

    for code, qty in shipment.items():
        canonical_code = kiln.sku(code)
        inv.add(canonical_code, qty)
        canonical_codes.add(canonical_code)

    return sum(inv.count(code) for code in canonical_codes)
